def load() -> pd.DataFrame:
    import pandas as pd

    path = "data/legal/input/csn-data-book-2024-csv/CSVs/2024_CSN_State_Top_Ten_Report_Categories.csv"

    # Read the file without header inference first, then promote the first non-empty row to header.
    raw = pd.read_csv(path, header=None, dtype=str)

    # Find the first row that looks like the header (contains 'State' and 'Category').
    def norm(x):
        return "" if x is None else str(x).strip()

    header_row_idx = None
    for i in range(len(raw)):
        row = [norm(v) for v in raw.iloc[i].tolist()]
        row_lc = [v.lower() for v in row]
        if "state" in row_lc and "category" in row_lc:
            header_row_idx = i
            break

    if header_row_idx is None:
        # Return the raw preview so the user can diagnose file structure.
        return raw.head(30)

    header = [norm(v) for v in raw.iloc[header_row_idx].tolist()]
    df = raw.iloc[header_row_idx + 1 :].copy()
    df.columns = header

    # Drop fully blank rows.
    df = df.dropna(how="all")

    # Normalize expected column names if there are minor variations.
    rename_map = {}
    for c in df.columns:
        c0 = norm(c)
        if c0.lower() == "# of reports" or c0.lower() == "number of reports":
            rename_map[c] = "# of Reports"
        if c0.lower() == "percent" or c0.lower() == "percentage":
            rename_map[c] = "Percentage"
    if rename_map:
        df = df.rename(columns=rename_map)

    # Filter out footer/source rows: keep only rows with a non-empty State value.
    if "State" in df.columns:
        df = df[df["State"].notna() & (df["State"].astype(str).str.strip() != "")]

    return df
